# Project instructions

This is a TypeScript / Next.js application. Answer questions about it and make
changes to it using the tools available to you in this working directory.

## Answer format contract (mandatory)

Your final message MUST follow the contract for the task type you were given.
The task prompt states its type. If it does not, infer it from the wording.

### `locate`, `reference`, `impact` tasks

Finish your final message with a single line, on its own, of exactly this form:

```
ANSWER: path/one.ts, path/two.tsx, path/three.ts
```

- Paths are **repository-relative** (relative to this working directory), e.g.
  `src/lib/permissions.ts` — never absolute, never prefixed with `./`.
- Separate paths with a comma. Order does not matter. Do not wrap the line in a
  code fence, do not add backticks, bullets, or trailing prose after it.
- List every file that answers the question and no others. Both missing files
  and extra files reduce your score.
- If the answer is genuinely the empty set, write `ANSWER:` with nothing after it.

### `explain` tasks

Answer in prose. Be concrete: name the actual files, functions, and types
involved, and describe the order in which they run. Do not emit an `ANSWER:`
line for these tasks.

### `fix` tasks

Edit the files needed to fix the described problem, then stop. Do not write a
summary report, do not create new documentation files, and do not emit an
`ANSWER:` line. The change is judged by running the test suite, so make the
edit and finish your turn as soon as the edit is complete.

## General rules

- Work only inside this working directory.
- Do not run `git` commands. Do not commit.
- Do not start dev servers or long-running watch processes.
- Do not install packages; the dependencies you need are already present.
----
import { z } from "zod";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
  UserId,
  WebhookId,
} from "@/types/common";

/**
 * Shared Zod primitives.
 *
 * Every schema in `src/schemas` is used twice: by `react-hook-form` through
 * `@hookform/resolvers/zod` on the client, and by the matching Server Action
 * on the server. Keep them free of server-only imports.
 */

const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/i;

/** Builds a branded-id schema whose output type is the branded alias. */
function brandedId<T extends string>(label: string) {
  return z
    .string()
    .regex(ULID, `${label} must be a ULID`)
    .transform((value) => value as T);
}

export const userIdSchema = brandedId<UserId>("userId");
export const orgIdSchema = brandedId<OrgId>("orgId");
export const projectIdSchema = brandedId<ProjectId>("projectId");
export const issueIdSchema = brandedId<IssueId>("issueId");
export const commentIdSchema = brandedId<CommentId>("commentId");
export const memberIdSchema = brandedId<MemberId>("memberId");
export const notificationIdSchema = brandedId<NotificationId>("notificationId");
export const activityIdSchema = brandedId<ActivityId>("activityId");
export const invitationIdSchema = brandedId<InvitationId>("invitationId");
export const labelIdSchema = brandedId<LabelId>("labelId");
export const attachmentIdSchema = brandedId<AttachmentId>("attachmentId");
export const subscriptionIdSchema = brandedId<SubscriptionId>("subscriptionId");
export const webhookIdSchema = brandedId<WebhookId>("webhookId");

export const isoTimestampSchema = z
  .iso
  .datetime()
  .transform((value) => value as IsoTimestamp);

export const emailSchema = z.email().max(254).toLowerCase();

export const sortDirectionSchema = z.enum(["asc", "desc"]);

export const pageRequestSchema = z.object({
  limit: z.number().int().min(1).max(100).default(25),
  cursor: z.string().nullable().optional(),
});

export const archiveScopeSchema = z.object({
  includeArchived: z.boolean().optional(),
});

export const hexColorSchema = z
  .string()
  .regex(/^#[0-9a-fA-F]{6}$/, "must be a #rrggbb color");

export type PageRequestInput = z.infer<typeof pageRequestSchema>;
export type ArchiveScopeInput = z.infer<typeof archiveScopeSchema>;
